#include "daw/mix_capture.h"
#include "cJSON.h"
#include <inttypes.h>
#include <math.h>
#include <stdio.h>
// Preserves optional frame identities without treating absent events as zero.
static void id(cJSON* j,const char* key,uint64_t v){if(v==UINT64_MAX){cJSON_AddNullToObject(j,key);return;}char text[32];snprintf(text,sizeof(text),"%" PRIu64,v);cJSON_AddStringToObject(j,key,text);}
// Resolves a region-relative production fence into authored timeline time.
static uint64_t absolute(uint64_t start,uint64_t relative){return relative==UINT64_MAX || relative>UINT64_MAX-start?UINT64_MAX:start+relative;}
// Describes evaluated control targets, including sampled click-protection floors, without extrapolating automation.
static void controls(cJSON* j,EngineInstrumentParams p,bool sampled){cJSON_AddNumberToObject(j,"release_control_ms",p.release_ms);cJSON_AddNumberToObject(j,"release_with_sample_floor_ms",sampled?fmax(4,p.release_ms):p.release_ms);cJSON_AddNumberToObject(j,"attack_ms",p.attack_ms);cJSON_AddNumberToObject(j,"decay_ms",p.decay_ms);cJSON_AddNumberToObject(j,"sustain",p.sustain);cJSON_AddNumberToObject(j,"level",p.level);cJSON_AddNumberToObject(j,"sustain_pedal",p.sustain_pedal);cJSON_AddNumberToObject(j,"release_noise",p.release_noise);}
// Serializes authored and prepared note endings with exact production ownership and range qualifications.
void daw_note_ending_json(cJSON* j,const DawMixCapture* c,int index) {
    const DawNoteEnding* n=&c->tails->notes[index];const DawMixSource* region=&c->snapshot->regions[n->source];id(j,"track_id",region->track_id);id(j,"clip_id",region->clip_id);cJSON_AddNumberToObject(j,"source_offset",n->source);cJSON_AddNumberToObject(j,"authored_note_index",n->note_index);cJSON_AddNumberToObject(j,"pitch",n->pitch);cJSON_AddNumberToObject(j,"velocity",n->velocity);id(j,"authored_onset_frame",absolute(region->start,n->authored_start));id(j,"authored_key_off_frame",absolute(region->start,absolute(n->authored_start,n->authored_gate)));id(j,"region_end_frame",absolute(region->start,region->duration));id(j,"next_distinct_viable_authored_track_onset_frame",n->next_onset);cJSON_AddBoolToObject(j,"viable_authored_trigger",n->eligible);cJSON_AddBoolToObject(j,"prepared_for_capture",n->prepared);
    if(!n->prepared){cJSON_AddStringToObject(j,"reason","source/note excluded by private export input horizon");return;}const EngineNoteEnding* p=&n->production;
    id(j,"prepared_key_off_frame",absolute(region->start,p->key_off));id(j,"damper_off_frame",absolute(region->start,p->damper_off));id(j,"source_render_fence_frame",absolute(region->start,p->source_end));id(j,"hat_choke_frame",absolute(region->start,p->choke));id(j,"mono_handoff_frame",absolute(region->start,p->handoff));id(j,"legato_chain_start_frame",absolute(region->start,p->chain_start));cJSON_AddBoolToObject(j,"legato",p->legato);cJSON_AddBoolToObject(j,"next_handoff_legato",p->next_legato);cJSON_AddBoolToObject(j,"mono",p->mono);cJSON_AddBoolToObject(j,"piano",p->piano);cJSON_AddBoolToObject(j,"one_shot_ignores_key_gate",p->one_shot);
    controls(cJSON_AddObjectToObject(j,"controls_at_onset"),p->onset_params,p->sampled);controls(cJSON_AddObjectToObject(j,"controls_at_damper_off"),p->key_off_params,p->sampled);controls(cJSON_AddObjectToObject(j,"controls_before_region_end"),p->boundary_params,p->sampled);
    cJSON_AddStringToObject(j,"semantics","prepared production fences and evaluated control targets; dynamic releases/sampled PCM may end earlier; no fabricated individual-note audible endpoint; source activity and FX tails are aggregate; future authored onset is not proof of audibility");
}
// Describes measured aggregate source activity after the last prepared damper-off within this capture.
void daw_source_tail_json(cJSON* j,const DawMixCapture* c,int source) {
    if(!c->snapshot->regions[source].midi){cJSON_AddBoolToObject(j,"available",false);cJSON_AddStringToObject(j,"reason","audio-file region has no MIDI voice ending diagnostics");return;}
    const DawSourceTailChannel* channels=c->tails->source[source];cJSON_AddBoolToObject(j,"source_audio_observed",channels[0].samples>0);cJSON_AddBoolToObject(j,"prepared",c->tails->prepared[source]);cJSON_AddNumberToObject(j,"threshold_amplitude",DAW_TAIL_THRESHOLD);cJSON_AddNumberToObject(j,"threshold_dbfs",-80);cJSON_AddStringToObject(j,"tap","MIDI source after instrument expressions, source clipping and source gain/pan automation; before authored track/region scalar gain, inserts and EQ");cJSON_AddStringToObject(j,"scope","measured range only; below-threshold does not mean mathematical silence; polyphonic notes and piano mechanics overlap; muted/zero-gain sources may not render; no extrapolated tail end or individual-note attribution");id(j,"last_prepared_damper_off_frame",c->tails->prepared[source] && c->tails->last_gate[source]?c->tails->last_gate[source]:UINT64_MAX);
    cJSON* array=cJSON_AddArrayToObject(j,"channels");for(int ch=0;ch<c->channels;++ch){const DawSourceTailChannel* m=&channels[ch];cJSON* item=cJSON_CreateObject();cJSON_AddItemToArray(array,item);cJSON_AddNumberToObject(item,"index",ch);id(item,"observed_samples",m->samples);id(item,"above_threshold_samples",m->active);id(item,"first_above_threshold_frame",m->active?m->first:UINT64_MAX);id(item,"last_above_threshold_frame",m->active?m->last:UINT64_MAX);cJSON_AddNumberToObject(item,"sample_peak",m->peak);cJSON_AddNumberToObject(item,"rms",m->samples?sqrt(m->power/m->samples):0);id(item,"post_last_damper_observed_samples",m->post_samples);id(item,"post_last_damper_above_threshold_samples",m->post_active);id(item,"post_last_damper_last_above_threshold_frame",m->post_active?m->post_last:UINT64_MAX);cJSON_AddNumberToObject(item,"post_last_damper_peak",m->post_peak);cJSON_AddNumberToObject(item,"post_last_damper_rms",m->post_samples?sqrt(m->post_power/m->post_samples):0);cJSON_AddBoolToObject(item,"right_censored_at_range_end",m->active && m->last+1==c->end);}
}
